// Shared types of the JSON schemas of the microservices: the Literal types of data_types.py (as enums) and the
// Schemas of the schema_types.json of each package, defined by the lowest package using them (e.g. GeodeId here, as
// Both OpenGeodeWeb-Back and OpenGeodeWeb-Viewer use it).
// A schema titled after one of them only names it ({"title": "GeodeId"}): the generated files get its definition
// (schema_definitions.json for the Python package at runtime), and the code generated from it uses the shared type

// Node imports
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const microserviceDir = path.dirname(fileURLToPath(import.meta.url));
// Values of each Literal type of data_types.py (generated by generate_data_types.py)
const dataTypes = readJson(
  path.join(microserviceDir, "src", "opengeodeweb_microservice", "database", "data_types.json"),
);

const ENUM_TYPES_TS_MODULE = "@geode/opengeodeweb-microservice/data_types";
const ENUM_TYPES_PYTHON_MODULE = "opengeodeweb_microservice.database.data_types";
// The value of the one value enum standing for an alias in the schemas given to quicktype (see aliasPlaceholders)
const ALIAS_PLACEHOLDER = "__schema_type__";
// Only the packages of this scope define schema types
const SCHEMA_TYPES_SCOPE = "@geode/";

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, "utf8"));
}

function isObject(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

// The directory of an installed package, looked up the way Node does: in the node_modules of a directory and its parents
function packageDirectory(name, fromDir) {
  for (let dir = fromDir; ; dir = path.dirname(dir)) {
    const candidate = path.join(dir, "node_modules", name);
    if (fs.existsSync(path.join(candidate, "package.json"))) {
      return fs.realpathSync(candidate);
    }
    if (path.dirname(dir) === dir) {
      return undefined;
    }
  }
}

// The packages of the scope installed in the node_modules of a package itself, not of its parents. The CI installs
// The dependencies of a package there, but without their "0.0.0" versions in its package.json. In the workspace, the
// Packages are installed in the node_modules of the workspace, and the package.json of each package lists them
function installedDependencies(packageDir) {
  const scopeDir = path.join(packageDir, "node_modules", SCHEMA_TYPES_SCOPE);
  if (!fs.existsSync(scopeDir)) {
    return [];
  }
  return fs
    .readdirSync(scopeDir)
    .filter((name) => fs.existsSync(path.join(scopeDir, name, "package.json")))
    .map((name) => `${SCHEMA_TYPES_SCOPE}${name}`);
}

// A package and its schema types: schema_types.json and the code generated from it are in its Python package
function packageLayer(packageDir) {
  const { name, dependencies = {} } = readJson(path.join(packageDir, "package.json"));
  const pythonPackage = name.replace(/^@[^/]+\//, "").replaceAll("-", "_");
  const jsonFile = path.join(packageDir, "src", pythonPackage, "schema_types.json");
  return {
    name,
    packageDir,
    pythonPackage,
    dependencies: [
      ...new Set([
        ...Object.keys(dependencies).filter((dependency) =>
          dependency.startsWith(SCHEMA_TYPES_SCOPE),
        ),
        ...installedDependencies(packageDir),
      ]),
    ],
    jsonFile,
    typescriptFile: jsonFile.replace(/\.json$/, ".d.ts"),
    pythonFile: jsonFile.replace(/\.json$/, ".py"),
    typescriptModule: `${name}/schema_types`,
    pythonModule: `${pythonPackage}.schema_types`,
  };
}

// The packages defining schema types seen by a package: its dependencies (recursively, the lowest first), then itself
function schemaTypesLayers(packageDir) {
  const layers = new Map();
  function visit(dir) {
    const layer = packageLayer(dir);
    if (layers.has(layer.name)) {
      return;
    }
    layers.set(layer.name, undefined);
    for (const dependency of layer.dependencies) {
      const dependencyDir = packageDirectory(dependency, dir);
      if (dependencyDir !== undefined) {
        visit(dependencyDir);
      }
    }
    layers.delete(layer.name);
    layers.set(layer.name, layer);
  }
  visit(fs.realpathSync(packageDir));
  return [...layers.values()]
    .filter((layer) => fs.existsSync(layer.jsonFile))
    .map((layer) => ({ ...layer, types: readJson(layer.jsonFile) }));
}

const INTERFACE_PATTERN = /^export interface (\w+) \{\n([^}]*)\}\n\n?/gm;
const UNION_PATTERN = /^export type (\w+) =([^;]*);\n\n?/gm;
// The shared interfaces may extend another one (see the "extends" of schema_types.json)
const SHARED_INTERFACE_PATTERN = /^export interface (\w+)(?: extends (\w+))? \{\n([^}]*)\}\n\n?/gm;
// The body of an Enum can hold its docstring, followed by a blank line
const PYTHON_ENUM_PATTERN = /^class (\w+)\(Enum\):\n((?:(?: {4}.*)?\n)+)/gm;
const PYTHON_DATACLASS_PATTERN =
  /^@dataclass\nclass (\w+)\(DataClassJsonMixin\):\n((?:(?:[ \t].*)?\n)*)/gm;
// The shared dataclasses may extend another one (see the "extends" of schema_types.json)
const SHARED_PYTHON_DATACLASS_PATTERN =
  /^@dataclass\nclass (\w+)\((\w+)\):\n((?:(?:[ \t].*)?\n)*)/gm;

function escapeRegExp(text) {
  return text.replaceAll(/[.*+?^${}()|[\]\\]/g, String.raw`\$&`);
}

// Quicktype aligns the fields of an interface: compare them without the alignment
function interfaceKey(body) {
  return body
    .split("\n")
    .map((line) => line.trim().replace(/:\s+/, ": "))
    .filter(Boolean)
    .toSorted()
    .join("\n");
}

function unionKey(union) {
  return union
    .split("|")
    .map((member) => member.trim())
    .filter(Boolean)
    .toSorted()
    .join(" | ");
}

// The fields of a dataclass, whatever its typing style (List or list)
function dataclassKey(body) {
  return body
    .split("\n")
    .map((line) => /^ {4}(\w+): (.+)$/.exec(line))
    .filter((match) => match !== null)
    .map(([, field, type]) => `${field}: ${type.replaceAll(/\bList\[/g, "list[")}`)
    .toSorted()
    .join("\n");
}

function enumKey(body) {
  return [...body.matchAll(/= (".*")$/gm)]
    .map(([, value]) => value)
    .toSorted()
    .join(" | ");
}

const enumKeys = Object.entries(dataTypes).map(([name, values]) => ({
  name,
  key: values
    .map((value) => JSON.stringify(value))
    .toSorted()
    .join(" | "),
}));

// Quicktype aligns the types of the fields of an interface: the fields of a body, aligned again
function alignFields(body) {
  const fields = [...body.matchAll(/^ {4}(\w+\??:) +/gm)].map(([, field]) => field);
  const width = Math.max(...fields.map((field) => field.length)) + 1;
  return body.replaceAll(/^ {4}(\w+\??:) +/gm, (_match, field) => `    ${field.padEnd(width)}`);
}

// Quicktype documents a field with a block comment above it: a one line description goes at the end of its line
function inlineFieldComments(content) {
  return content.replaceAll(/^(export interface .*\{\n)([^}]*)\}/gm, (block, header, body) => {
    const inlined = body.replaceAll(
      /^( +)\/\*\*\n\1 \* (.+)\n\1 \*\/\n\1(.+;)$/gm,
      (_match, indent, comment, field) => `${indent}${field} // ${comment}`,
    );
    return inlined === body ? block : `${header}${alignFields(inlined)}}`;
  });
}

// The schema types seen by the package of a directory
function loadSchemaTypes(packageDir) {
  const layers = schemaTypesLayers(packageDir);
  const ownLayer = layers.find((layer) => layer.packageDir === fs.realpathSync(packageDir));

  const definedBy = new Map(Object.keys(dataTypes).map((name) => [name, undefined]));
  for (const layer of layers) {
    for (const name of Object.keys(layer.types)) {
      // Packages not depending on each other may define the same type (e.g. ViewerId, by OpenGeodeWeb-Back and
      // OpenGeodeWeb-Viewer): a package depending on both sees them as one, the same definition
      const other = definedBy.get(name);
      if (
        other !== undefined &&
        JSON.stringify(other.types[name]) === JSON.stringify(layer.types[name])
      ) {
        continue;
      }
      if (definedBy.has(name)) {
        throw new Error(
          `${layer.jsonFile}: ${name} is already defined differently by ${other?.name ?? "data_types.py"}`,
        );
      }
      definedBy.set(name, layer);
    }
  }
  const definitions = {
    ...Object.fromEntries(
      Object.entries(dataTypes).map(([name, values]) => [name, { type: "string", enum: values }]),
    ),
    ...Object.fromEntries(layers.flatMap((layer) => Object.entries(layer.types))),
  };

  // A definition with the shared types it uses (titled schemas) replaced by theirs
  function resolveDefinition(schema) {
    if (Array.isArray(schema)) {
      return schema.map((item) => resolveDefinition(item));
    }
    if (!isObject(schema)) {
      return schema;
    }
    if (schema.title in definitions && Object.keys(schema).length === 1) {
      return { title: schema.title, ...resolveDefinition(definitions[schema.title]) };
    }
    // "extends": an object type with the properties of another one, plus its own
    if (schema.extends !== undefined) {
      const { extends: baseName, ...own } = schema;
      const base = resolveDefinition(definitions[baseName]);
      const resolvedOwn = resolveDefinition(own);
      return {
        ...base,
        ...resolvedOwn,
        properties: { ...base.properties, ...resolvedOwn.properties },
        required: [...base.required, ...(resolvedOwn.required ?? [])],
      };
    }
    return Object.fromEntries(
      Object.entries(schema).map(([key, value]) => [key, resolveDefinition(value)]),
    );
  }

  const resolvedDefinitions = Object.fromEntries(
    Object.entries(definitions).map(([name, definition]) => [name, resolveDefinition(definition)]),
  );

  // The type each object type extends, if any
  const baseTypeNames = Object.fromEntries(
    Object.entries(definitions)
      .filter(([, definition]) => definition.extends !== undefined)
      .map(([name, definition]) => [name, definition.extends]),
  );

  // The object types of a package, generated as dataclasses and interfaces
  function objectTypeNames(layer) {
    return Object.keys(layer.types).filter((name) => resolvedDefinitions[name].type === "object");
  }

  // A schema titled after a shared type only holds its title, and its own description if the type has none
  function stubSchema(schema) {
    const definition = resolvedDefinitions[schema.title];
    const description =
      schema.description !== undefined && definition.description === undefined
        ? { description: schema.description }
        : {};
    return { title: schema.title, ...description };
  }

  // Reduces every schema titled after a shared type to its stub. Returns whether the schema changed
  function stubSchemaTypes(schema) {
    if (Array.isArray(schema)) {
      return schema.map((item) => stubSchemaTypes(item)).some(Boolean);
    }
    if (!isObject(schema)) {
      return false;
    }
    if (schema.title in resolvedDefinitions) {
      const stub = stubSchema(schema);
      if (JSON.stringify(schema) === JSON.stringify(stub)) {
        return false;
      }
      for (const key of Object.keys(schema)) {
        delete schema[key];
      }
      Object.assign(schema, stub);
      return true;
    }
    let changed = false;
    for (const value of Object.values(schema)) {
      changed = stubSchemaTypes(value) || changed;
    }
    return changed;
  }

  // A copy of a schema with the definition of every shared type it uses (the same expansion as the
  // Resolve_schema_types of opengeodeweb_microservice.schemas, at runtime)
  function resolveSchemaTypes(schema) {
    if (Array.isArray(schema)) {
      return schema.map((item) => resolveSchemaTypes(item));
    }
    if (!isObject(schema)) {
      return schema;
    }
    if (schema.title in resolvedDefinitions) {
      return { ...schema, ...resolvedDefinitions[schema.title] };
    }
    return Object.fromEntries(
      Object.entries(schema).map(([key, value]) => [key, resolveSchemaTypes(value)]),
    );
  }

  // Whether a schema uses a shared type
  function usesSchemaTypes(schema) {
    if (Array.isArray(schema)) {
      return schema.some((item) => usesSchemaTypes(item));
    }
    if (!isObject(schema)) {
      return false;
    }
    return schema.title in resolvedDefinitions || Object.values(schema).some(usesSchemaTypes);
  }

  // The definitions of the shared types, read by the Python package at runtime to resolve its schemas
  const project = packageLayer(fs.realpathSync(packageDir));
  const definitionsFile = path.join(
    project.packageDir,
    "src",
    project.pythonPackage,
    "schema_definitions.json",
  );
  function writeDefinitions(used) {
    if (!used) {
      fs.rmSync(definitionsFile, { force: true });
      return;
    }
    const sorted = Object.fromEntries(
      Object.keys(resolvedDefinitions)
        .toSorted()
        .map((name) => [name, resolvedDefinitions[name]]),
    );
    fs.writeFileSync(definitionsFile, `${JSON.stringify(sorted, null, 2)}\n`);
  }

  // The key of each declaration of the generated code of packages, with the fields it inherits from the type it extends
  function inheritedKeys(sourceLayers, fileOf, pattern, keyOf) {
    const bodies = new Map();
    for (const layer of sourceLayers) {
      for (const [, name, , body] of fs.readFileSync(fileOf(layer), "utf8").matchAll(pattern)) {
        bodies.set(name, { body, layer });
      }
    }
    function fullBody(name) {
      const base = baseTypeNames[name];
      const { body } = bodies.get(name);
      return base === undefined ? body : `${fullBody(base)}\n${body}`;
    }
    return [...bodies].map(([name, { layer }]) => ({ name, layer, key: keyOf(fullBody(name)) }));
  }

  // The non object types (e.g. DataId), generated as aliases: the generated code names them instead of their type
  const aliasLayers = new Map(
    layers.flatMap((layer) =>
      Object.keys(layer.types)
        .filter((name) => resolvedDefinitions[name].type !== "object")
        .map((name) => [name, layer]),
    ),
  );

  // A copy of a resolved schema for quicktype, where each schema titled after an alias is a one value enum: quicktype
  // Declares a type for it, replaced by the alias (see sharedTypes)
  function aliasPlaceholders(schema) {
    if (Array.isArray(schema)) {
      return schema.map((item) => aliasPlaceholders(item));
    }
    if (!isObject(schema)) {
      return schema;
    }
    if (aliasLayers.has(schema.title)) {
      const description =
        schema.description === undefined ? {} : { description: schema.description };
      // Its own title: quicktype names its type after it, never like a type of the module (e.g. the Visibility params)
      return {
        title: `SchemaType${schema.title}`,
        ...description,
        type: "string",
        enum: [`${ALIAS_PLACEHOLDER}${schema.title}`],
      };
    }
    return Object.fromEntries(
      Object.entries(schema).map(([key, value]) => [key, aliasPlaceholders(value)]),
    );
  }

  // Replacement of the declarations matching the shared types of some packages (by default all of them) by imports.
  // The aliases of localLayer, whose code is being generated, are only renamed
  function sharedTypes(sourceLayers = layers, localLayer = undefined) {
    function aliasKeys(moduleOf) {
      return [...aliasLayers]
        .filter(([, layer]) => sourceLayers.includes(layer) || layer === localLayer)
        .map(([name, layer]) => [
          JSON.stringify(`${ALIAS_PLACEHOLDER}${name}`),
          { name, module: layer === localLayer ? undefined : moduleOf(layer) },
        ]);
    }
    // The shared TypeScript types, by the key of their declaration
    const typescriptAliasKeys = new Map(aliasKeys((layer) => layer.typescriptModule));
    const typescriptKeys = new Map([
      ...enumKeys.map(({ name }) => [
        unionKey(dataTypes[name].map((value) => JSON.stringify(value)).join(" | ")),
        { name, module: ENUM_TYPES_TS_MODULE },
      ]),
      ...inheritedKeys(
        sourceLayers,
        (layer) => layer.typescriptFile,
        SHARED_INTERFACE_PATTERN,
        interfaceKey,
      ).map(({ name, layer, key }) => [key, { name, module: layer.typescriptModule }]),
    ]);
    // The shared Python types: the aliases by the key of their placeholder enum, the other ones by name
    const pythonAliasKeys = new Map(aliasKeys((layer) => layer.pythonModule));
    const pythonKeys = new Map([
      ...enumKeys.map(({ name, key }) => [name, { key, module: ENUM_TYPES_PYTHON_MODULE }]),
      ...inheritedKeys(
        sourceLayers,
        (layer) => layer.pythonFile,
        SHARED_PYTHON_DATACLASS_PATTERN,
        dataclassKey,
      ).map(({ name, layer, key }) => [name, { key, module: layer.pythonModule }]),
    ]);

    // Removes the declarations of the shared types (each shared one of its declarations), renaming their uses
    // The kept names stay declared, as aliases of their shared type (e.g. a response that is a Point3D)
    function replaceDeclarations(content, declarations, sharedOf, used, keptNames = new Set()) {
      let result = content;
      const renamed = new Map();
      for (const declaration of declarations) {
        const shared = sharedOf(declaration);
        if (shared === undefined) {
          continue;
        }
        used.push(shared);
        if (keptNames.has(declaration.name)) {
          result = result.replace(
            declaration.declaration,
            `export type ${declaration.name} = ${shared.name};\n\n`,
          );
        } else {
          renamed.set(declaration.name, shared.name);
          result = result.replace(declaration.declaration, "");
        }
      }
      for (const [name, sharedName] of renamed) {
        if (name !== sharedName) {
          result = result.replaceAll(new RegExp(`\\b${escapeRegExp(name)}\\b`, "g"), sharedName);
        }
      }
      return result;
    }

    // The import lines of the used shared types, one per module
    function importLines(used, line) {
      const imports = Map.groupBy(
        used.filter(({ module }) => module !== undefined),
        ({ module }) => module,
      );
      return [...imports].map(([module, types]) =>
        line(module, [...new Set(types.map(({ name, imported }) => imported ?? name))].toSorted()),
      );
    }

    function typescriptDeclarations(content) {
      return [
        ...[...content.matchAll(INTERFACE_PATTERN)].map(([declaration, name, body]) => ({
          declaration,
          name,
          key: interfaceKey(body),
        })),
        ...[...content.matchAll(UNION_PATTERN)].map(([declaration, name, union]) => ({
          declaration,
          name,
          key: unionKey(union),
        })),
      ];
    }

    // Quicktype declares its own type for each use of a shared type, named after its path when it is used by
    // Several routes: replace every declaration matching a shared type by an import of it. The aliases first, as
    // The shared interfaces use them. The kept names (e.g. the params and responses of the routes, referenced
    // Elsewhere) stay declared as aliases of their shared type
    function useSharedTypescriptTypes(content, keptNames = new Set()) {
      const used = [];
      const withAliases = replaceDeclarations(
        content,
        typescriptDeclarations(content),
        ({ key }) => typescriptAliasKeys.get(key),
        used,
        keptNames,
      );
      const result = replaceDeclarations(
        withAliases,
        typescriptDeclarations(withAliases),
        ({ key }) => typescriptKeys.get(key),
        used,
        keptNames,
      );
      const lines = importLines(
        used,
        (module, names) => `import type { ${names.join(", ")} } from "${module}";\n`,
      );
      return lines.length === 0 ? result : `${lines.join("")}\n${result}`;
    }

    // Quicktype declares its own Enum or dataclass for each shared type, named after its title: import the shared
    // One instead when it is the same type (the enums are Literal types, so the values stay plain strings)
    function useSharedPythonTypes(content) {
      const used = [];
      const enums = (text) =>
        [...text.matchAll(PYTHON_ENUM_PATTERN)].map(([declaration, name, body]) => ({
          declaration,
          name,
          key: enumKey(body),
        }));
      // A module declaring a class named after an alias (e.g. the Visibility params of visibility.py) imports it as
      // VisibilityType
      const classNames = new Set([...content.matchAll(/^class (\w+)\(/gm)].map(([, name]) => name));
      const withAliases = replaceDeclarations(
        content,
        enums(content),
        ({ key }) => {
          const shared = pythonAliasKeys.get(key);
          if (shared === undefined || !classNames.has(shared.name)) {
            return shared;
          }
          const renamed = `${shared.name}Type`;
          return { ...shared, name: renamed, imported: `${shared.name} as ${renamed}` };
        },
        used,
      );
      const sameType = ({ name, key }) => {
        const shared = pythonKeys.get(name);
        return shared !== undefined && shared.key === key
          ? { name, module: shared.module }
          : undefined;
      };
      let result = replaceDeclarations(
        withAliases,
        [
          ...enums(withAliases),
          ...[...withAliases.matchAll(PYTHON_DATACLASS_PATTERN)].map(
            ([declaration, name, body]) => ({
              declaration,
              name,
              key: dataclassKey(body),
            }),
          ),
        ],
        sameType,
        used,
      );
      if (used.length === 0) {
        return content;
      }
      if (!/\(Enum\):/.test(result)) {
        result = result.replace(/^from enum import Enum\n/m, "");
      }
      const lines = importLines(
        used,
        (module, names) => `from ${module} import ${names.join(", ")}\n`,
      );
      return `${lines.join("")}${result}`;
    }

    return { useSharedPythonTypes, useSharedTypescriptTypes };
  }

  return {
    baseTypeNames,
    layers,
    objectTypeNames,
    ownLayer,
    resolvedDefinitions,
    aliasPlaceholders,
    // The types the generated code imports instead of declaring them
    sharedTypeNames: new Set(Object.keys(resolvedDefinitions)),
    resolveSchemaTypes,
    sharedTypes,
    stubSchemaTypes,
    usesSchemaTypes,
    writeDefinitions,
  };
}

export { inlineFieldComments, loadSchemaTypes };
